let virtualWallet=WalletModel.empty();
window.WalletPort={async getBalance(){return {status:'available',balanceCents:virtualWallet.balances.buyer||0,currency:'CNY'};}};
function walletTransaction(ids,action,reason=''){const selected=ids.map(id=>{const o=demoOrders.find(x=>x.id===id);if(!o)throw Error('订单不存在');return o;});const changed=selected.map(o=>OrderModel.move(o,action,reason));let next=virtualWallet;if(action==='pay')next=WalletModel.pay(next,selected);else if(action==='approve'||action==='receive')for(const o of selected)next=WalletModel.release(next,o.id,action==='approve');virtualWallet=next;demoOrders=demoOrders.map(o=>changed.find(x=>x.id===o.id)||o);}
function showWallet(account='buyer'){const balance=virtualWallet.balances[account]||0,pending=Object.values(virtualWallet.holds).filter(h=>h.seller===account).reduce((n,h)=>n+h.amount,0);const rows=virtualWallet.entries.filter(e=>e.account===account);modal(account==='buyer'?'我的钱包':'店铺钱包 · 模拟账号',`<span class="tag">平台虚拟货币</span><section class="walletHero"><div><span>可用余额</span><h1>${money(balance/100)}</h1></div><div><span>待结算金额</span><h2>${money(pending/100)}</h2><small>买家确认收货后到账，暂不可消费</small></div></section><div class="orderActions"><h3>资金明细</h3>${account==='buyer'?'<button id="walletRecharge" class="primary">充值</button>':''}</div><div class="walletLedger">${rows.length?rows.map(e=>`<article class="walletLine"><div><b>${e.type}</b><p class="muted">${e.time}</p>${e.type==='充值'?'<small>虚拟充值</small>':`<small>订单 ${escapeHTML(e.ref)}</small>`}</div><div><strong class="${e.delta>0?'income':''}">${e.delta>0?'+':'−'}${money(Math.abs(e.delta)/100)}</strong><p class="muted">余额 ${money(e.balance/100)}</p></div></article>`).join(''):'<div class="empty">暂无资金记录，充值后开始体验。</div>'}</div><div class="orderActions"><button id="walletBack">${account==='buyer'?'返回我的':'返回店铺订单'}</button><span class="muted">仅用于校园虚拟交易</span></div>`);if($('walletRecharge'))$('walletRecharge').onclick=()=>showRecharge(()=>showWallet());$('walletBack').onclick=()=>account==='buyer'?showMine():showSellerOrders(orderSeller);}
function showRecharge(back=()=>showWallet()){modal('充值',`<span class="tag">平台虚拟货币 · 不涉及真实支付</span><p>当前可用余额 <strong>${money((virtualWallet.balances.buyer||0)/100)}</strong></p><form id="rechargeForm"><label class="reportField">充值金额<input id="rechargeAmount" inputmode="decimal" placeholder="大于 0，单次最多 1,000"></label><div class="rechargePresets">${[100,200,500].map(n=>`<button type="button" data-recharge="${n}">${n}</button>`).join('')}</div><p class="muted">支持自定义金额，最多两位小数。</p><p id="rechargeError" role="alert"></p><div class="orderActions"><button type="button" id="rechargeBack">返回</button><button type="submit" class="primary">确认充值</button></div></form>`);document.querySelectorAll('[data-recharge]').forEach(b=>b.onclick=()=>{$('rechargeAmount').value=b.dataset.recharge;});$('rechargeBack').onclick=back;const key='R'+Date.now();$('rechargeForm').onsubmit=e=>{e.preventDefault();try{const cents=WalletModel.amount($('rechargeAmount').value.trim());virtualWallet=WalletModel.credit(virtualWallet,'buyer',cents,'充值',key);modal('充值成功',`<span class="tag">虚拟充值</span><h2>已到账 ${money(cents/100)}</h2><p>可用余额 ${money(virtualWallet.balances.buyer/100)}</p><button class="primary" id="rechargeContinue">返回继续操作</button>`);$('rechargeContinue').onclick=back;}catch(err){$('rechargeError').textContent=err.message;}};}
function walletPaymentError(target,error,retry){target.textContent=error.message;if(error.message==='余额不足'){target.insertAdjacentHTML('beforeend',' <button id="paymentRecharge" type="button">去充值</button>');$('paymentRecharge').onclick=()=>showRecharge(retry);}}
showGroupPayment=function(group){const rows=demoOrders.filter(o=>o.group===group&&o.status==='待付款');modal('统一付款',`<span class="tag">平台虚拟货币</span><h2>${rows.length} 笔待付款订单</h2><p>应付合计 <strong>${money(rows.reduce((n,o)=>n+o.totalCents,0)/100)}</strong></p><p>可用余额 ${money((virtualWallet.balances.buyer||0)/100)}</p><p class="muted">付款后金额进入订单待结算，买家确认收货后结算给店主。</p><p id="groupPaymentError" role="alert"></p><div class="orderActions"><button id="payLater">稍后付款</button><button id="payGroup" class="primary" ${rows.length?'':'disabled'}>确认余额付款</button></div>`);$('payLater').onclick=()=>showOrders('待付款');$('payGroup').onclick=()=>{try{walletTransaction(rows.map(o=>o.id),'pay');showOrders('待发货');}catch(e){walletPaymentError($('groupPaymentError'),e,()=>showGroupPayment(group));}};};
const walletMineBase=showMine;showMine=function(){walletMineBase();$('dialogBody').insertAdjacentHTML('beforeend','<div class="accountEntries"><button id="myWallet"><span><strong>我的钱包</strong><small>虚拟充值 · 资金明细 · 待结算金额</small></span><span>→</span></button></div>');$('myWallet').onclick=()=>showWallet();const reset=$('resetDemo').onclick;$('resetDemo').onclick=()=>{virtualWallet=WalletModel.empty();reset();};};$('mine').onclick=showMine;
const walletSellerOrdersBase=showSellerOrders;showSellerOrders=function(shop=orderSeller??0){walletSellerOrdersBase(shop);$('dialogBody').querySelector('.orderBottom').insertAdjacentHTML('beforeend','<button id="sellerWallet">查看店铺资金</button>');$('sellerWallet').onclick=()=>showWallet(+shop===0?'buyer':'seller:'+shop);};
const walletSellerContentBase=sellerContent;sellerContent=function(section){const html=walletSellerContentBase(section);if(section!=='overview')return html;const pending=Object.values(virtualWallet.holds).filter(h=>h.seller==='buyer').reduce((n,h)=>n+h.amount,0);return `<section class="applicationCard walletOverview"><span>可用余额 ${money((virtualWallet.balances.buyer||0)/100)} · 待结算 ${money(pending/100)}</span><button id="sellerOwnWallet">查看资金明细</button></section>`+html;};sellerReviewPage.addEventListener('click',e=>{if(e.target.closest('#sellerOwnWallet'))showWallet();});
seedOrders=function(){modal('载入资金流程示例',`<p>将新增一笔 500 虚拟充值及示例订单，并生成对应扣款、退款与结算流水。</p><p>已有订单和余额会保留，示例仅可载入一次。</p><button id="confirmWalletSeed" class="primary">载入示例</button>`);$('confirmWalletSeed').onclick=()=>{if(demoOrders.some(o=>o.group==='SAMPLE')){showOrders();toast('示例已经载入');return;}virtualWallet=WalletModel.credit(virtualWallet,'buyer',50000,'充值','SAMPLE-RECHARGE');const states=['待付款','待发货','待收货','已完成','退款审核中','已退款','已取消'];states.forEach((status,i)=>{const p=products.filter(p=>p.variants[0].stock>0&&!p.editorId)[i];const o=OrderModel.create([{id:p.id,variant:0,quantity:1}],products,'SAMPLE')[0];o.id='示例-'+(i+1);const reservedBatch=[o];reservePlacedOrders(reservedBatch);demoOrders.unshift(...reservedBatch);if(status==='已取消')walletTransaction([o.id],'cancel');else if(status!=='待付款'){walletTransaction([o.id],'pay');if(['待收货','已完成'].includes(status))walletTransaction([o.id],'ship');if(status==='已完成')walletTransaction([o.id],'receive');if(['退款审核中','已退款'].includes(status))walletTransaction([o.id],'request');if(status==='已退款')walletTransaction([o.id],'approve');}});showOrders();};};
